 "관계·태그·저자 그래프 사용": "Enable the citation, tag and author graphs",
 "관련 논문": "Related papers",
 "관련 논문 보기": "Related papers view",
 "관련 논문은 문헌 하나를 기준으로 찾습니다. 문헌을 하나만 선택하세요.": "Related papers are found from one paper. Select a single item.",
 "관련 논문의 SNS·웹 반응에 Altmetric 점수를 더합니다. api.altmetric.com에만 보내며, 비워 두면 Bluesky·Hacker News·Wikipedia만 찾습니다.": "Adds the Altmetric score to a paper's social and web reactions. Sent only to api.altmetric.com; left empty, only Bluesky, Hacker News and Wikipedia are searched.",
 "관련 문헌": "Related",
 "관련 문헌으로 연결": "Link as related",
 "관련 항목 {0}": "Related items {0}",
 "관심 저자": "Followed",
 "관심 저자 {0}": "Followed authors {0}",
 "관심 저자 {0}명": "{0} followed authors",
 "관심 저자 {0}명 중 {1}명이 서로 함께 썼습니다": "{1} of the {0} followed authors have written together",
 "관심 저자 {0}명과 함께 썼습니다": "has written with {0} followed authors",
 "관심 저자 {0}명의 새 논문을 OpenAlex 요청 약 {1}회로 확인합니다 (논문이 많으면 조금 더)": "Checks the {0} followed authors for new papers in about {1} OpenAlex requests (a few more when there are many papers)",
 "관심 저자 {0}명의 새 논문을 확인하는 중…": "Checking {0} followed authors for new papers…",
 "관심 저자 공저 관계 그래프": "Followed authors co-authorship graph",
 "관심 저자 사이에 함께 쓴 논문이 아직 보이지 않습니다. 새 논문을 확인하면 공저 관계가 여기에 그려집니다.": "No paper written together by followed authors has turned up yet. Once new papers are checked, their co-authorship is drawn here.",
 "관심 저자 사이의 공저 관계": "Co-authorship among followed authors",
 "관심 저자 새 논문": "New work by followed authors",
 "관심 저자 정렬": "Sort followed authors",
 "관심 저자 찾기": "Find a followed author",
 "관심 저자 특허": "Patents of followed authors",
 "관심 저자: {0}명 확인, 새 논문 없음": "Followed authors: {0} checked, nothing new",
 "관심 저자: {0}명이 새 논문 {1}편": "Followed authors: {1} new papers by {0}",
 "관심 저자는 {0}명까지 저장합니다. 목록에서 몇 명을 해제하세요.": "At most {0} followed authors are kept. Unwatch a few from the list.",
 "관심 저자로 등록": "Watch this author",
 "관심 저자에서 빼기": "Stop following",
 "관심 저자의 사진을 Wikidata(ORCID로, Wikimedia Commons의 사진), Google Scholar, ORCID에 적힌 개인 홈페이지 순서로 찾습니다. 저자를 열 때, ‘사진 찾기’를 누를 때, 새 논문 확인이 끝난 뒤 아직 찾지 않은 사람만 찾습니다. 찾은 것과 못 찾은 것은 두 달 동안 다시 묻지 않습니다.": "Looks for followed authors' photos on Wikidata (by ORCID, a Wikimedia Commons photo), then Google Scholar, then the personal homepage listed in ORCID. Asked when you open an author, when you press Find photos, and after a news check for people not looked up yet. A find or a miss is not asked again for two months.",
 "관심 저자의 사진을 찾는 중… Wikidata, Google Scholar, 각자의 홈페이지를 확인합니다.": "Looking for photos of followed authors… checking Wikidata, Google Scholar and their own homepages.",
 "관심 저자의 특허 출원·등록을 찾는 데만 씁니다. data.uspto.gov에서 MyUSPTO 계정으로 무료 발급됩니다. 키는 api.uspto.gov에만 보내며, 비워 두면 특허 확인은 건너뜁니다.": "Used only to find patents filed or granted to followed authors. Free from data.uspto.gov with a MyUSPTO account. The key is sent to api.uspto.gov only; left empty, the patent check is skipped.",
 "관심 해제": "Unwatch",
