 "규칙 추가": "Add a rule",
 "규칙 편집": "edit rule",
 "그 밖의 저널": "Other journals",
 "그 사이 내용이 바뀌어 아무것도 쓰지 않았습니다. 바뀐 내용을 확인하고 다시 고르세요.": "The text changed in the meantime, so nothing was written. Check the new text and choose again.",
 "그 사이 메모가 또 바뀌어 아무것도 쓰지 않았습니다. 바뀐 내용을 확인하고 다시 고르세요.": "The memo changed again in the meantime, so nothing was written. Check what changed, then choose again.",
 "그 사이 상황이 바뀌어 아무것도 바꾸지 않았습니다. 바뀐 내용을 확인하고 다시 고르세요.": "Things changed in the meantime, so nothing was changed. Check what changed, then choose again.",
 "그 사이 상황이 바뀌어 아무것도 쓰지 않았습니다. 바뀐 내용을 확인하고 다시 고르세요.": "Things changed in the meantime, so nothing was written. Check what changed, then choose again.",
 "그 사이 열린 PDF가 바뀌었거나 닫혔습니다.": "The active reader changed or closed.",
 "그 사이 열린 PDF가 바뀌었습니다.": "The active reader changed.",
 "그 사이 열린 PDF나 선택이 바뀌었습니다. 다시 선택한 뒤 실행하세요.": "The active reader or selection changed.",
 "그 탭은 이미 닫혔습니다.": "Tab no longer exists.",
 "그때 다시 실행하면 남은 것부터 이어서 채웁니다. 지금까지 받은 값은 이미 저장했습니다.": "Run it again then and it will carry on from where it stopped. What has arrived is already saved.",
 "그래프 거르기": "Filter the graph",
 "그래프 도구": "Graph tools",
 "그래프 범위": "Graph scope",
 "그래프 종류": "Kind of graph",
 "그래프 최대 문헌 수": "Maximum items in the graph",
 "그래프 한 장에 낱낱이 그리고 인용 정보를 가져오는 최대 문헌 수입니다. 이보다 많은 범위는 주제 묶음으로 접어 보여 주고(최대 2,000편), 묶음을 누르면 그 논문들이 펼쳐집니다.": "The most papers a graph draws one by one and fetches citation data for. A larger scope is folded into topic bubbles (up to 2,000 papers); pressing a bubble opens its papers.",
