 "기본 순서": "Default order",
 "기본 주석 색": "Default annotation colors",
 "기본값으로 되돌렸습니다.": "Back at the defaults.",
 "기본값으로 되돌리지 못했습니다: ": "Could not restore the default: ",
 "기본값은 영어입니다. 패널은 바로 바뀌고, 문헌 목록의 열 이름과 오른쪽 클릭 메뉴는 Zotero를 다시 시작하면 바뀝니다.": "English is the default. The panel changes at once; item list column names and the right-click menu change when Zotero restarts.",
 "기본값은 영어입니다. 한국어를 고르면 패널이 한국어로 바뀝니다. Zotero 언어 따르기는 Zotero가 한국어일 때만 한국어를 씁니다. 패널은 바로 바뀌고, 문헌 목록의 열 이름은 Zotero를 다시 시작하면 바뀝니다.": "English is the default. Select Simplified Chinese or Korean, or follow Zotero. Restart Zotero to update column names.",
 "기존 태그 경로": "Existing tag path",
 "기존 태그 경로와 새 태그 경로를 모두 입력하세요.": "Enter both the old and the new tag path.",
 "기준 {0}편 중 참고문헌 기록 {1}편": "{1} of {0} read papers have reference lists",
 "기초": "Foundations",
