 "마지막에 이름을 올린 저자를 이 논문의 책임저자로 보고, 그 사람의 최근 논문·소속 이동·특허를 엽니다.": "Takes the last-listed author as the paper's senior author and opens their recent papers, moves between institutions and patents.",
