 "본문만": "Body only",
 "본문만 읽기": "Read body only",
 "본문만 읽습니다": "Reads the body only",
 "본문만 읽어 줍니다. 그림·표 캡션, 참고문헌, 머리말·꼬리말·쪽 번호는 건너뜁니다(Zotero의 읽어주기는 페이지의 글을 모두 읽습니다). PDF에서 Alt(Option)+더블클릭하거나 글을 선택해 ‘여기서부터 듣기’를 누르면 그 문장부터 읽습니다.": "Reads the body only: figure and table captions, references, running heads, footers and page numbers are skipped (Zotero's own Read Aloud reads everything on the page). Alt(Option)+double-click in the PDF, or select text and choose ‘Listen from here’, to start at that sentence.",
 "본문을 모으는 중…": "Gathering the body text…",
 "본문을 읽지 못해 초록만 참고했습니다.": "The text could not be read, so only the abstract was used.",
 "본인 논문으로 표시합니다. 이 논문의 소속과 공저자는 다음부터 이 저자를 가리는 근거가 됩니다": "Marks this as the author's own paper. Its affiliation and coauthors then count as evidence for this author",
