 "비교할 문헌 두 편을 고르세요": "Pick two papers to compare",
 "비교할 문헌을 추가하세요.": "Add papers to compare.",
 "비밀번호로 가려 표시합니다. 분류 기본값 복원으로 지워지지 않습니다.": "Shown masked, like a password. Restoring a category's defaults does not clear it.",
 "비어 있음": "Empty",
 "비우면 아래 기능이 꺼져 있습니다.": "Leave these blank and the features below stay off.",
 "비워 두면 기본 개요(핵심 주장 · 논리 흐름 · 근거의 강점·한계 · 공통 기반 · 논쟁 여지와 판가름할 증거 · 열린 질문)를 씁니다. 출력 언어와 '지어내지 말 것'은 항상 덧붙습니다.": "Left empty, the default outline is used (core claim · line of argument · strength and limits of the evidence · common ground · points of contention with the deciding evidence · open questions). The output language and 'do not invent' are always appended.",
 "비워 두면 논문 언어에 맞는 시스템 음성을 자동으로 고릅니다. 리더 패널의 ‘목소리’ 메뉴에서 고르면 여기에 저장됩니다. 음성은 내 컴퓨터에 설치된 것만 쓰며 인터넷으로 보내지 않습니다.": "Left empty, a system voice that matches the paper's language is chosen automatically. A voice picked in the reader panel's Voice menu is saved here. Only voices installed on this computer are used, and nothing is sent over the internet.",
 "비워 두면 이 Mac의 AI 브리지를 찾아 씁니다. 브리지는 이 Mac에 로그인된 Claude 계정으로 답하고, Claude가 한도에 걸리거나 답하지 못하면 ChatGPT 계정으로 답합니다(API 키 없음, 각 계정의 사용 한도 적용). 설치·제거는 플러그인 폴더의 bridge/install.sh, bridge/install.sh --uninstall. 다른 서버를 쓰려면 Chat Completions 형식 주소를 넣으세요. 이 주소가 항상 우선합니다. 예: https://api.openai.com/v1/chat/completions, 로컬 Ollama는 http://localhost:11434/v1/chat/completions": "Leave empty to use the AI bridge on this Mac. The bridge answers with the Claude account logged in on this Mac, and with the ChatGPT account when Claude hits its limit or cannot answer (no API key; each account's usage limits apply). Install or remove it with bridge/install.sh or bridge/install.sh --uninstall in the plugin folder. To use another server, enter a Chat Completions address; it always takes precedence. E.g. https://api.openai.com/v1/chat/completions; for a local Ollama, http://localhost:11434/v1/chat/completions",
 "비중": "Share",
