 "이 수를 넘는 주석은 「더 보기」를 누를 때 이어서 그립니다. 주석이 수백 개인 서재에서 탭이 빨리 열립니다.": "Anything past this is drawn when you press Show more. It is what makes the tab open quickly in a library with hundreds of annotations.",
