 "컬렉션을 찾을 수 없습니다. 삭제되었을 수 있습니다.": "Collection is unavailable.",
 "컬렉션이 없습니다.": "No collections.",
 "켜면 논문을 열 때(논문마다 한 번) 제목·초록·본문 일부를 AI로 보내 요약을 만듭니다. 주소를 비워 두면 이 Mac의 AI 브리지(Claude·ChatGPT 계정의 사용 한도를 씀)로, 주소를 넣으면 그 서버로 보냅니다. 서버가 요금을 받는 서비스라면 열 때마다 비용이 듭니다. 그래서 기본은 꺼짐이고, 꺼져 있으면 리더 패널의 ‘요약 만들기’ 버튼을 눌러야만 보냅니다. 이 Mac에서 실행하는 로컬 모델(Ollama 등, http://localhost:11434/v1/chat/completions)을 연결하면 요청이 이 Mac 밖으로 나가지 않습니다. 한 번 만든 요약은 저장해 두고 다시 보내지 않습니다.": "When on, opening a paper (once per paper) sends its title, abstract and part of the text to the AI to make a summary: to the AI bridge on this Mac (using your Claude or ChatGPT account's allowance) when the address is blank, else to the server entered above. If that server charges for use, each paper opened costs money, so this is off by default; while it is off, nothing is sent unless you press Make summary in the reader panel. With a local model that runs on this Mac (Ollama and similar, http://localhost:11434/v1/chat/completions), the requests do not leave this Mac. A summary, once made, is kept and not sent again.",
