 "AI 요약·대화·제목 번역·함께 읽기 결과를 쓸 언어입니다. 기본값은 패널 언어를 따르며, 전문 용어는 논문에 쓰인 영어 그대로 둡니다. 리더 패널의 문단 번역 언어는 ‘논문 번역 언어’가 따로 정합니다.": "AI摘要、聊天、标题翻译和一起阅读的语言是编写的。默认情况下，它遵循面板的语言；技术术语在论文撰写时仍保留英文。读者小组的段落翻译有自己的“论文翻译语言”。",
