 "AI는 이 Mac의 AI 브리지를 자동으로 찾아 쓰고, 다른 서버·모델·번역기와 요청 문구는 여기서 정합니다. 요청은 버튼을 누를 때만 보냅니다. ‘논문을 열면 AI 요약을 자동으로 만들기’를 켜면 논문을 열 때도 보냅니다.": "当人工智能找到一个桥接器时，它会使用本机 上的桥接器；此处设置另一个服务器、模型、翻译器和请求措辞。仅当您按下按钮时才会发送请求，如果启用了“打开论文时自动生成 AI 摘要”，则当论文打开时也会发送请求。",
