 "api.openalex.org에만 보냅니다. openalex.org 계정에서 무료로 받습니다. 비워 두고 ZotPoP에 넣은 키가 있으면 그 키를 씁니다. 둘 다 없으면 목록의 자동 인용 수 조회가 멈추고, 우클릭 → 선택한 문헌 인용 수 새로고침과 논문 추가·수정 때의 조회만 하루 약 10건 됩니다.": "仅发送至 api.openalex.org。从您的 openalex.org 帐户免费获取一个。如果留空，则使用 ZotPoP 中输入的密钥（如果有）。如果两者都没有，列表的自动引文查找就会停止；右键单击 → 刷新所选项目的引用计数，添加或编辑论文时的查找仍然有效，每天大约 10 次。",
