 "if-catalog.json · journal-registry.json · jcr-categories.json 세 파일을 이 폴더에서 먼저 찾고, 없으면 배포본을 씁니다.": "首先在此文件夹中查找 if-catalog.json、journal-registry.json 和 jcr-categories.json 三个文件，否则从随附的存档中获取。",
 "mailto 없음 — 익명 대기열을 씁니다. 설정 → 연락 이메일에 주소를 넣으면 빨라집니다.": "no mailto — 请求使用匿名队列。设置→联系电子邮件使他们更快。",
