 "격식체 쪽": "更正式",
 "결과": "结果",
 "결과 복사": "复制结果",
 "계정이 아닙니다. Crossref는 요청 URL에 ?mailto=주소를 붙이면 익명 요청보다 빠른 대기열(polite pool)에 넣어 줍니다. OpenAlex에도 같은 주소가 붙지만 지금은 속도 이점이 없습니다. 입력한 주소는 이 두 서비스의 서버 기록에 요청마다 남습니다. 비워 두면 ZotPoP의 연락처 이메일이 있으면 그것을 쓰고, 둘 다 없으면 보내지 않습니다(조회는 그대로 동작하되 익명 대기열을 씁니다). Zotero 로그인 계정을 대신 쓰는 일은 없습니다.": "这不是一个帐户。 Crossref 将携带 ?mailto=your-address 的请求放入比匿名请求更快的队列中 - 它的礼貌池。 OpenAlex 也接收地址，但现在没有速度优势。作为交换，您输入的地址会出现在每个请求的这两个服务的服务器日志中。留空，如果有则使用 ZotPoP 的联系电子邮件；两者都没有，则不会发送任何内容：查找仍然有效，它们只是使用匿名队列。您的 Zotero 登录信息永远不会被使用。",
