 "관심 저자에서 빼기": "停止关注",
 "관심 저자의 사진을 Wikidata(ORCID로, Wikimedia Commons의 사진), Google Scholar, ORCID에 적힌 개인 홈페이지 순서로 찾습니다. 저자를 열 때, ‘사진 찾기’를 누를 때, 새 논문 확인이 끝난 뒤 아직 찾지 않은 사람만 찾습니다. 찾은 것과 못 찾은 것은 두 달 동안 다시 묻지 않습니다.": "在 Wikidata 上查找关注作者的照片（由 ORCID 拍摄，维基共享资源照片），然后在 Google Scholar 上查找，然后在 ORCID 中列出的个人主页。当您打开作者、按“查找照片”时以及在新闻检查后查找尚未查找的人员时会询问。两个月内不会再次询问找到或错过的情况。",
 "관심 저자의 사진을 찾는 중… Wikidata, Google Scholar, 각자의 홈페이지를 확인합니다.": "寻找关注作者的照片……检查 Wikidata、Google Scholar 和他们自己的主页。",
 "관심 저자의 특허 출원·등록을 찾는 데만 씁니다. data.uspto.gov에서 MyUSPTO 계정으로 무료 발급됩니다. 키는 api.uspto.gov에만 보내며, 비워 두면 특허 확인은 건너뜁니다.": "仅用于查找已向关注的作者申请或授予的专利。使用 MyUSPTO 帐户可免费从 data.uspto.gov 获取。密钥仅发送至 api.uspto.gov；留空，将跳过专利检查。",
