 "리더 패널의 ‘번역’에서 문단별 번역에만 씁니다. deepl.com에서 무료 키(:fx로 끝남, 한 달 50만 자)를 받을 수 있고, 키 끝으로 무료/유료 서버를 알아서 고릅니다. 키는 DeepL 서버의 인증 헤더에만 보내며 번역 버튼을 눌렀을 때(번역 전에 이번 달 남은 양을 묻는 요청 포함)만 사용합니다. 번역기는 DeepL → Translate for Zotero(설치되어 있으면) → AI 순서로 고르며, 한 번역기가 멈추면 패널에서 다음 번역기로 그 실행이 맡았던 문단 중 남은 것만 이어서 번역할 수 있습니다.": "仅用于阅读器面板的翻译选项卡中的段落翻译。 Deepl.com 提供免费密钥（以 :fx 结尾，每月 500,000 个字符），并从密钥末尾选择免费或付费服务器。该密钥仅在其授权标头中指向 DeepL，并且仅在您按下翻译按钮时（包括翻译前提出的本月剩余津贴请求）。翻译器按 DeepL → 翻译 Zotero（如果已安装）→ AI 的顺序进行尝试；当其中一个停止时，小组可以继续处理下一个运行中剩余的段落。",
