 "비어 있음": "空",
 "비우면 아래 기능이 꺼져 있습니다.": "将这些留空，下面的功能将保持关闭状态。",
 "비워 두면 기본 개요(핵심 주장 · 논리 흐름 · 근거의 강점·한계 · 공통 기반 · 논쟁 여지와 판가름할 증거 · 열린 질문)를 씁니다. 출력 언어와 '지어내지 말 것'은 항상 덧붙습니다.": "留空，则使用默认大纲（核心主张·论证思路·证据的强度和局限性·共同点·与决定性证据的争论点·开放性问题）。始终附加输出语言和“不发明”。",
 "비워 두면 논문 언어에 맞는 시스템 음성을 자동으로 고릅니다. 리더 패널의 ‘목소리’ 메뉴에서 고르면 여기에 저장됩니다. 음성은 내 컴퓨터에 설치된 것만 쓰며 인터넷으로 보내지 않습니다.": "留空时，系统会自动选择与论文语言相匹配的系统语音。在阅读器面板的“语音”菜单中选取的语音保存在此处。仅使用此计算机上安装的语音，不会通过互联网发送任何内容。",
 "비워 두면 이 Mac의 AI 브리지를 찾아 씁니다. 브리지는 이 Mac에 로그인된 Claude 계정으로 답하고, Claude가 한도에 걸리거나 답하지 못하면 ChatGPT 계정으로 답합니다(API 키 없음, 각 계정의 사용 한도 적용). 설치·제거는 플러그인 폴더의 bridge/install.sh, bridge/install.sh --uninstall. 다른 서버를 쓰려면 Chat Completions 형식 주소를 넣으세요. 이 주소가 항상 우선합니다. 예: https://api.openai.com/v1/chat/completions, 로컬 Ollama는 http://localhost:11434/v1/chat/completions": "留空以使用本机 上的 AI 桥。桥接器使用在本机 上登录的 Claude 帐户进行应答，并在 Claude 达到限制或无法应答时使用 ChatGPT 帐户进行应答（无 API 密钥；每个帐户的使用限制适用）。使用插件文件夹中的bridge/install.sh 或bridge/install.sh --uninstall 安装或删除它。要使用其他服务器，请输入 Chat Completions 地址；它总是优先的。例如。 https://api.openai.com/v1/chat/completions; 为本地 Ollama，http://localhost:11434/v1/chat/completions",
