 "켜면 논문을 열 때(논문마다 한 번) 제목·초록·본문 일부를 AI로 보내 요약을 만듭니다. 주소를 비워 두면 이 Mac의 AI 브리지(Claude·ChatGPT 계정의 사용 한도를 씀)로, 주소를 넣으면 그 서버로 보냅니다. 서버가 요금을 받는 서비스라면 열 때마다 비용이 듭니다. 그래서 기본은 꺼짐이고, 꺼져 있으면 리더 패널의 ‘요약 만들기’ 버튼을 눌러야만 보냅니다. 이 Mac에서 실행하는 로컬 모델(Ollama 등, http://localhost:11434/v1/chat/completions)을 연결하면 요청이 이 Mac 밖으로 나가지 않습니다. 한 번 만든 요약은 저장해 두고 다시 보내지 않습니다.": "启用后，打开一篇论文（每篇论文一次）会将其标题、摘要和部分文本发送到 AI 进行摘要：当地址为空时，发送到本机 上的 AI 桥（使用您的 Claude 或 ChatGPT 帐户的配额），否则发送到上面输入的服务器。如果该服务器收费，则每打开一张论文都要花钱，所以默认关闭；当它关闭时，除非您按阅读器面板中的“生成摘要”，否则不会发送任何内容。对于在本机 上运行的本地模型（Ollama 和类似的 http://localhost:11434/v1/chat/completions),），请求不会离开本机。摘要一旦生成，就会保留，不会再次发送。",
